<?php require '../includes/functions.php';$pageTitle='Sign in';$errors=[];if(post()){verify_csrf();$email=strtolower(textval('email'));$key=auth_key($email,'customer');if(auth_blocked($key))$errors[]='Too many attempts. Try again in 15 minutes.';else{$u=query('SELECT * FROM users WHERE email=?',[$email])->fetch();if($u&&password_verify(textval('password'),$u['password'])&&$u['is_active']){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));query('DELETE FROM login_attempts WHERE attempt_key=?',[$key]);redirect('dashboard.php');}fail_login($key);$errors[]='Email or password is incorrect, or the account is unavailable.';}}require '../includes/header.php';?><section class="container section"><div class="auth-panel panel"><span class="eyebrow">WELCOME BACK</span><h1>Sign in</h1><?php errors($errors);?><form method="post" data-validate><?php csrf();?><label>Email address<input name="email" type="email" required maxlength="190" autocomplete="email" value="<?=e(textval('email'))?>"></label><label>Password<input name="password" type="password" maxlength="72" autocomplete="current-password" required></label><button class="full">Sign in</button></form><p>New here? <a href="<?=e(url('auth/register.php'))?>">Create an account</a></p></div></section><?php require '../includes/footer.php';?>
